def fis(c):
    with open(S + c, encoding='utf-8') as f:
        return sum(1 for _ in f)
citite = ['lectii/_sim/excelx-sortare.js', 'lectii/_sim/excelx-grafic.js', 'lectii/_sim/excelx-decizie.js', 'lectii/_sim/excelx-proiect.js',
          'lectii/_sim/excelx-test.js', 'jocuri/_motor/tip-excel.js', 'lectii/viii/m1-l04/index.html', 'jocuri/excel-antrenament-viii/index.html',
          'jocuri/excel-viii/index.html', 'jocuri/_motor/tip-foaie.js']
fisiere = [{"cale": c, "linii": fis(c)} for c in citite]
fisiere[-1]["nota"] = "citit parțial: antetul, evaluarea (1-160) și tipul „foaie” (190-263)"

functii = []
for i, t in enumerate(F, 1):
    fu, gr, ge, vd, un, ce, ex, bi, bd, li, no = t
    functii.append({"id": f"excel-b-F{i:03d}", "functie": fu, "grup": gr, "gest": ge, "vechi_dovada": vd, "unde": un,
                    "ceruta_de_exercitiu": ce, "exercitii": ex, "biblioteca": bi, "biblioteca_dovada": bd, "lipsa": li, "nota": no})

# verificarea dovezilor vechi: linia există
rele = []
for fn in functii:
    for d in fn["vechi_dovada"]:
        c, l = d.rsplit(':', 1)
        n = fis(c)
        if not (1 <= int(l) <= n): rele.append((fn["id"], d))
assert not rele, rele

